echo "=== render ==="; ../ln -n mixed2.json 2>&1 | cat -A; echo "EXIT=${PIPESTATUS[0]}"; echo "=== sql ==="; ../ln -n mixed2.json -c ';SELECT log_line, log_time, log_level, log_raw_text FROM all_logs' 2>&1

cd /tmp/jsonlogs-probe-9x1 && mkdir -p pretty && cd pretty && cat > pretty.json <<'EOF'
